import os
import torch
import random
import numpy as np


class Config:
    """
    Configuration for the Tri-Architecture Heterogeneous Ensemble pipeline.
    Includes paths, hyperparameters, and constants derived from the strategy.
    """

    # ==========================================
    # Paths & Directories
    # ==========================================
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_10"

    # Ensure working directory exists
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Metadata File Paths
    # Generated by the metadata script
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Data Source Directories
    # Strategy specifies using Filtered Spectrograms
    FILTERED_SPECTROGRAM_DIR = os.path.join(
        INPUT_ROOT, "supplemental_data", "filtered_spectrograms"
    )

    # Output Paths
    SUBMISSION_PATH = os.path.join(WORKING_DIR, "submission.csv")

    # ==========================================
    # Data Configuration
    # ==========================================
    # Dimensions: (Height, Width) corresponding to (Frequency, Time)
    # Strategy: Rectangular Resolution 1:2 aspect ratio
    IMAGE_SIZE = (224, 448)

    NUM_CLASSES = 19
    N_FOLDS = 5

    # Debugging flags to control dataset size
    DEBUG = False
    DEBUG_SUBSET_SIZE = 50

    # ==========================================
    # Model Configuration
    # ==========================================
    # List of architectures for the heterogeneous ensemble
    # Cite solution_lesson_node_00034: Heterogeneous Ensemble (ResNet18 + DenseNet121)
    ARCHITECTURES = ["resnet18", "densenet121"]

    # ==========================================
    # Training Configuration
    # ==========================================
    BATCH_SIZE = 16
    NUM_WORKERS = 2

    # Optimization Strategy: Defined by Total Update Steps rather than Epochs
    MAX_STEPS = 1000
    VAL_CHECK_INTERVAL = 50  # Validate every 50 steps

    # Optimizer Hyperparameters
    LEARNING_RATE = 1e-4  # Constant LR
    WEIGHT_DECAY = 1e-4  # Conservative weight decay

    # Augmentation Hyperparameters
    MIXUP_ALPHA = 0.4  # Mild Mixup

    # ==========================================
    # System & Reproducibility
    # ==========================================
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    SEED = 42

    @staticmethod
    def set_seed(seed=42):
        """
        Sets fixed random seeds for python, numpy, and torch to ensure reproducibility.
        """
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)

        # Enforce deterministic behavior
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False


# Initialize environment with fixed seed upon import
Config.set_seed(Config.SEED)
